#include <array>
#include <cstddef>
#include <cstdint>

// The four bytes of value in little-endian order: lowest byte first.
std::array<std::uint8_t, 4> toBytes(std::uint32_t value)
{
    std::array<std::uint8_t, 4> bytes{};
    for (std::size_t i{ 0 }; i < bytes.size(); ++i)
    {
        bytes[i] = static_cast<std::uint8_t>(value & 0xFF);   // keep only the lowest eight bits
        value >>= 8;                                          // bring the next byte down
    }
    return bytes;
}

// The number made by four little-endian bytes.
std::uint32_t fromBytes(const std::array<std::uint8_t, 4>& bytes)
{
    std::uint32_t value{ 0 };
    for (std::size_t i{ bytes.size() }; i > 0; --i)
    {
        value = (value << 8) | bytes[i - 1];                  // start from the highest byte
    }
    return value;
}

unitTests:
TEST("the lesson's example") {
    CHECK(toBytes(0x12345678) == (std::array<std::uint8_t, 4>{ 0x78, 0x56, 0x34, 0x12 }));
}
TEST("a small number only uses the first byte") {
    CHECK(toBytes(1) == (std::array<std::uint8_t, 4>{ 1, 0, 0, 0 }));
}
TEST("one thousand is E8 03 00 00") {
    CHECK(toBytes(1000) == (std::array<std::uint8_t, 4>{ 0xE8, 0x03, 0x00, 0x00 }));
}
TEST("every bit on") {
    CHECK(toBytes(0xFFFFFFFFu) == (std::array<std::uint8_t, 4>{ 0xFF, 0xFF, 0xFF, 0xFF }));
}
TEST("bytes back to a number") {
    CHECK_EQ(fromBytes({ 0x78, 0x56, 0x34, 0x12 }), 0x12345678u);
    CHECK_EQ(fromBytes({ 0xE8, 0x03, 0x00, 0x00 }), 1000u);
    CHECK_EQ(fromBytes({ 0, 0, 0, 0x80 }), 0x80000000u);
}
TEST("there and back again") {
    CHECK_EQ(fromBytes(toBytes(3735928559u)), 3735928559u);
    CHECK_EQ(fromBytes(toBytes(0)), 0u);
}

